INSERT INTO `VersieSectie` VALUES (56,12,6,'VERKOOPOVEREENKOMST (COMPROMIS)','pending'),(57,12,7,'1. PARTIJEN\n\n1.1 VERKOPER:\nNaam: [placeholder:NAAM_VERKOPER] Adres: [placeholder:ADRES_VERKOPER]\nRijksregisternummer/KBO: [placeholder:ID_VERKOPER]\n\n1.2 KOPER:\nNaam: [placeholder:NAAM_KOPER]\nAdres: [placeholder:ADRES_KOPER]\nRijksregisternummer: [placeholder:ID_KOPER]','pending'),(58,12,8,'2. BESCHRIJVING VAN HET GOED\nHet onroerend goed gelegen te [[ADRES_PAND]], gekend ten kadaster onder\n[[KADASTRELE_GEGEVENS]].\nOppervlakte volgens kadaster: [[OPPERVLAKTE]].','pending'),(59,12,9,'3. PRIJS EN BETALING\nDe verkoop is gesloten voor de prijs van [[VERKOOPPRIJS]] euro.\nVoorschot/waarborg (10%): [[WAARBORG_BEDRAG]], te storten op de derdenrekening\nvan de notaris/makelaar.','pending'),(60,12,10,'4. SPECIFIEKE CLAUSULES & ATTESTEN\nEPC-waarde: Het goed heeft een energiescore van [[EPC_SCORE]] kWh/m².\nAsbest: Het asbestattest met referentie [[ASBEST_REF]] werd overhandigd.\nOpschortende voorwaarde: Deze overeenkomst wordt gesloten onder de opschortende\nvoorwaarde van het verkrijgen van een lening voor een bedrag van [[BEDRAG_LENING]]\nvoor een termijn van [[TERMIJN_LENING]].','pending'),(61,13,6,'VERKOOPOVEREENKOMST (COMPROMIS)','pending'),(62,13,7,'1. PARTIJEN\n\n1.1 VERKOPER:\nNaam: [[NAAM_VERKOPER]] Adres: [[ADRES_VERKOPER]]\nRijksregisternummer/KBO: [[ID_VERKOPER]]\n\n1.2 KOPER:\nNaam: [[NAAM_KOPER]]\nAdres: [[ADRES_KOPER]]\nRijksregisternummer: [[ID_KOPER]]','pending'),(63,13,8,'2. BESCHRIJVING VAN HET GOED\nHet onroerend goed gelegen te [[ADRES_PAND]], gekend ten kadaster onder\n[[KADASTRELE_GEGEVENS]].\nOppervlakte volgens kadaster: [[OPPERVLAKTE]].','pending'),(64,13,9,'3. PRIJS EN BETALING\nDe verkoop is gesloten voor de prijs van [[VERKOOPPRIJS]] euro.\nVoorschot/waarborg (10%): [[WAARBORG_BEDRAG]], te storten op de derdenrekening\nvan de notaris/makelaar.','pending'),(65,13,10,'4. SPECIFIEKE CLAUSULES & ATTESTEN\nEPC-waarde: Het goed heeft een energiescore van [[EPC_SCORE]] kWh/m².\nAsbest: Het asbestattest met referentie [[ASBEST_REF]] werd overhandigd.\nOpschortende voorwaarde: Deze overeenkomst wordt gesloten onder de opschortende\nvoorwaarde van het verkrijgen van een lening voor een bedrag van [[BEDRAG_LENING]]\nvoor een termijn van [[TERMIJN_LENING]].','pending'),(66,14,6,'VERKOOPOVEREENKOMST (COMPROMIS)','pending'),(67,14,7,'1. PARTIJEN\n\n1.1 VERKOPER:\nNaam: [[NAAM_VERKOPER]] Adres: [[ADRES_VERKOPER]]\nRijksregisternummer/KBO: [[ID_VERKOPER]]\n\n1.2 KOPER:\nNaam: [[NAAM_KOPER]]\nAdres: [[ADRES_KOPER]]\nRijksregisternummer: [[ID_KOPER]]','pending'),(68,14,8,'2. BESCHRIJVING VAN HET GOED\nHet onroerend goed gelegen te [[ADRES_PAND]], gekend ten kadaster onder\n[[KADASTRELE_GEGEVENS]].\nOppervlakte volgens kadaster: [[OPPERVLAKTE]].','pending'),(69,14,9,'3. PRIJS EN BETALING\nDe verkoop is gesloten voor de prijs van [[VERKOOPPRIJS]] euro.\nVoorschot/waarborg (10%): [[WAARBORG_BEDRAG]], te storten op de derdenrekening\nvan de notaris/makelaar.','pending'),(70,14,10,'4. SPECIFIEKE CLAUSULES & ATTESTEN\nEPC-waarde: Het goed heeft een energiescore van [[EPC_SCORE]] kWh/m².\nAsbest: Het asbestattest met referentie [[ASBEST_REF]] werd overhandigd.\nOpschortende voorwaarde: Deze overeenkomst wordt gesloten onder de opschortende\nvoorwaarde van het verkrijgen van een lening voor een bedrag van [[BEDRAG_LENING]]\nvoor een termijn van [[TERMIJN_LENING]].','pending'),(71,15,6,'VERKOOPOVEREENKOMST (COMPROMIS)','pending'),(72,15,7,'1. PARTIJEN\n\n1.1 VERKOPER:\nNaam: [[NAAM_VERKOPER]] Adres: [[ADRES_VERKOPER]]\nRijksregisternummer/KBO: [[ID_VERKOPER]]\n\n1.2 KOPER:\nNaam: [[NAAM_KOPER]]\nAdres: [[ADRES_KOPER]]\nRijksregisternummer: [[ID_KOPER]]','pending'),(73,15,8,'2. BESCHRIJVING VAN HET GOED\nHet onroerend goed gelegen te [[ADRES_PAND]], gekend ten kadaster onder\n[[KADASTRELE_GEGEVENS]].\nOppervlakte volgens kadaster: [[OPPERVLAKTE]].','pending'),(74,15,9,'3. PRIJS EN BETALING\nDe verkoop is gesloten voor de prijs v